package org.nonfood.oilplants.web;
import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import org.nonfood.oilplants.dao.*;import org.nonfood.oilplants.service.ImageStorage;import java.io.*;
@WebServlet("/admin/plants/image/delete") public class AdminImageDeleteServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{String plant=r.getParameter("plantId");try{WebSupport.requireAdmin(r);long plantId=Long.parseLong(plant),imageId=Long.parseLong(r.getParameter("imageId"));String stored=new PlantDao().deleteImage(plantId,imageId);if(stored!=null)ImageStorage.delete(stored);new AuditDao().log(WebSupport.user(r).getId(),"IMAGE_DELETE","plant",plantId,"image "+imageId,r.getRemoteAddr());r.getSession().setAttribute("flash",stored==null?"图片记录不存在。":"图片已删除。");}catch(Exception e){r.getSession().setAttribute("flash","删除图片失败："+e.getMessage());}s.sendRedirect(r.getContextPath()+"/admin/plants/form?id="+plant);}}
